#!/bin/bash
set -eo pipefail
/data1/home/sunyiq/miniconda3/envs/knet_clean/bin/python -I -B - <<'WRR_PYTHON'
"""Read registered files only; return an encrypted envelope, no model execution."""
import base64,gzip,hashlib,io,json,os,subprocess,tarfile,tempfile
from datetime import datetime,timezone
from pathlib import Path

requested=json.loads(base64.b64decode(''))
certificate=base64.b64decode('')
allowed_roots=[Path('/data1/home/sunyiq/kalmannet_wrr_hp_extension_20260902').resolve(),
               Path('/data1/home/sunyiq/kalmannet_wrr_finalist_replication_20260907').resolve()]
members={}
manifest=[]
for item in requested:
    path=Path(item['remote_path'])
    resolved=path.resolve()
    if not any(root==resolved or root in resolved.parents for root in allowed_roots):
        raise RuntimeError('Requested path escaped the two registered completed-training roots')
    if not path.is_file():raise RuntimeError('Missing registered file: '+str(path))
    if path.stat().st_size>10_000_000:raise RuntimeError('Unexpected size: '+str(path))
    raw=path.read_bytes();actual=hashlib.sha256(raw).hexdigest()
    if item['expected_sha256'] and actual!=item['expected_sha256']:
        raise RuntimeError('Hash mismatch: '+str(path))
    members[item['local_member']]=raw
    manifest.append(dict(item,actual_sha256=actual,bytes=len(raw)))
report=dict(collected_at_utc=datetime.now(timezone.utc).isoformat(),files=manifest,
            model_execution=False,training=False,original_files_modified=False)
members['remote_manifest.json']=json.dumps(report,ensure_ascii=False,indent=2).encode('utf-8')
buffer=io.BytesIO()
with tarfile.open(fileobj=buffer,mode='w') as tar:
    for name,raw in sorted(members.items()):
        info=tarfile.TarInfo(name);info.size=len(raw);info.mode=0o600
        tar.addfile(info,io.BytesIO(raw))
payload=gzip.compress(buffer.getvalue(),compresslevel=6,mtime=0)
# OpenSSL performs hybrid public-key encryption. Only the certificate travels
# through the existing public mailbox; the private key remains on the workstation.
with tempfile.TemporaryDirectory(prefix='wrr_readonly_export_') as tmp:
    cert_path=Path(tmp)/'public_cert.pem';cert_path.write_bytes(certificate)
    proc=subprocess.run(['openssl','smime','-encrypt','-aes256','-binary','-outform','DER',str(cert_path)],
                        input=payload,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=45)
    if proc.returncode:raise RuntimeError('OpenSSL envelope failed: '+proc.stderr.decode('utf-8','replace'))
    encrypted=proc.stdout
for row in manifest:
    if hashlib.sha256(Path(row['remote_path']).read_bytes()).hexdigest()!=row['actual_sha256']:
        raise RuntimeError('Source changed during retrieval: '+row['remote_path'])
print('BEGIN_WRR_ENCRYPTED_EXPORT')
print(json.dumps({'format':'openssl-smime-DER-aes256','payload_sha256':hashlib.sha256(payload).hexdigest(),
                  'encrypted_sha256':hashlib.sha256(encrypted).hexdigest(),
                  'encrypted_bytes':len(encrypted),'file_count':len(manifest),
                  'encrypted_base64':base64.b64encode(encrypted).decode()}))
print('END_WRR_ENCRYPTED_EXPORT')

WRR_PYTHON
